package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all conditional statements in the parent
    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]
    cond.ir_type == "ConditionalStatement"
    cond.type == 2  # SWITCH type
    cond.is_top == true

    # Check if there's no default case in the entire chain by collecting all conditions in the chain
    chain_conditions := collect_chain_conditions(cond)
    has_default := count([c | c := chain_conditions[_]; c.is_default == true]) > 0
    not has_default

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in switch expression - The switch statement does not have a default case. (CWE-478)"
