# Helper function to collect all conditions in the else chain without recursion
collect_chain_conditions(cond) = conditions {
    conditions := {c | c := cond; c.ir_type == "ConditionalStatement"}
    else_chain := collect_else_chain(cond.else_statement)
    conditions := conditions | else_chain
}

collect_else_chain(else_cond) = conditions {
    else_cond == null
    conditions := set()
} else {
    conditions := {c | c := else_cond; c.ir_type == "ConditionalStatement"}
    next_chain := collect_else_chain(else_cond.else_statement)
    conditions := conditions | next_chain
}

